effect.shader:
vec3 hash3(vec2 p) {
  vec3 q = vec3(
    dot(p, vec2(127.1, 311.7)),
    dot(p, vec2(269.5, 183.3)),
    dot(p, vec2(419.2, 371.9))
  );
  return fract(sin(q) * 43758.5453);
}

float gradientNoise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);

  float n = mix(
    mix(
      dot(-1.0 + 2.0 * hash3(i).xy, f - vec2(0.0, 0.0)),
      dot(-1.0 + 2.0 * hash3(i + vec2(1.0, 0.0)).xy, f - vec2(1.0, 0.0)),
      u.x
    ),
    mix(
      dot(-1.0 + 2.0 * hash3(i + vec2(0.0, 1.0)).xy, f - vec2(0.0, 1.0)),
      dot(-1.0 + 2.0 * hash3(i + vec2(1.0, 1.0)).xy, f - vec2(1.0, 1.0)),
      u.x
    ),
    u.y
  );

  return 0.5 + 0.5 * n;
}

float fbm(vec2 p) {
  float v = 0.0;
  float amp = 0.5;
  float freq = 1.0;
  for (int i = 0; i < 4; i++) {
    v += amp * gradientNoise(p * freq);
    freq *= 2.0;
    amp *= 0.5;
  }
  return v;
}

void main() {
  vec2 iResolution = acScreenSize;
  vec2 fragCoord = acScreenNorm * iResolution;
  vec2 uv = fragCoord / iResolution;
  float aspect = iResolution.x / iResolution.y;

  float noiseScale = 3.0;
  float dissolveMap = fbm(uv * vec2(aspect, 1.0) * noiseScale + 10.0);

  float t = progress * 1.6;
  float solidAlpha = smoothstep(t - 0.05, t + 0.05, dissolveMap);

  vec3 finalColor = vec3(0.0);

  if (solidAlpha > 0.001) {
    vec3 imgCol = texture2DCv(inputImg.texture, uv).rgb;
    finalColor = imgCol * solidAlpha;
  }

  float gridDim = density;
  vec2 dims = vec2(gridDim * aspect, gridDim);
  vec2 cellSize = 1.0 / dims;
  vec2 id = floor(uv * dims);

  int range = 2;
  for (int y = -2; y <= 2; y++) {
    for (int x = -2; x <= 2; x++) {
      vec2 offset = vec2(float(x), float(y));
      vec2 neighborID = id + offset;

      vec2 origin = (neighborID + 0.5) * cellSize;

      vec3 rnd = hash3(neighborID);

      float pThreshold = fbm(origin * vec2(aspect, 1.0) * noiseScale + 10.0);

      if (t < pThreshold) {
        continue;
      }

      float age = t - pThreshold;

      float z = 1.0 + (age * zDist);
      if (z < 0.05) {
        continue;
      }

      if (z > 1.0 && solidAlpha > 0.5) {
        continue;
      }

      vec2 flow = vec2(
        gradientNoise(neighborID * 0.1 + age),
        gradientNoise(neighborID * 0.1 + age + 100.0)
      ) - 0.5;
      vec2 jitter = rnd.xy - 0.5;

      vec2 posOffset = (flow * 0.8 + jitter * 0.2) * scatter * age;

      vec2 worldPos = (origin - 0.5) * aspect;
      worldPos += posOffset;

      vec2 projectedPos = worldPos / z;
      projectedPos.x /= aspect;
      vec2 screenPos = projectedPos + 0.5;

      vec2 diff = uv - screenPos;
      diff.x *= aspect;
      float dist = length(diff);

      float pSize = size * (0.8 + 0.4 * rnd.z);
      float radius = (0.5 * pSize) / density / z;

      float alpha = 1.0 - smoothstep(radius * 0.5, radius, dist);

      if (alpha > 0.0) {
        vec3 pCol = texture2DCv(inputImg.texture, origin).rgb;

        float distFade = 1.0;
        if (z > 1.0) {
          distFade = 1.0 / (1.0 + age * 2.0);
        } else {
          distFade = smoothstep(0.05, 0.3, z);
        }

        alpha *= distFade;

        finalColor = mix(finalColor, pCol, alpha);
      }
    }
  }

  gl_FragColor = vec4(finalColor, 1.0);
}
